('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Netzwerkanbindung eines PCs ignorieren?', 2, '[{"text": "DNS-Server", "correct": false, "because": "Wichtig für Namensauflösung"}, {"text": "Optisches Design des Routers", "correct": true, "because": "Kein Einfluss auf Funktion"}, {"text": "Netzwerkprotokoll", "correct": false, "because": "Entscheidend für Kommunikation"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
