('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für die Berechnung des Gewinns wichtig?', 5, '[{"text": "Umsatz", "correct": true, "because": "Grundlage des Gewinns"}, {"text": "Fixkosten", "correct": true, "because": "Beeinflussen Gewinn"}, {"text": "Schriftart der Berichte", "correct": false, "because": "Kein Einfluss"}, {"text": "Variable Kosten", "correct": true, "because": "Reduzieren Gewinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Berechnung des Gewinns ignorieren?', 2, '[{"text": "Fixkosten", "correct": false, "because": "Wichtig für Gewinn"}, {"text": "Farbe der Kalkulationstabelle", "correct": true, "because": "Kein Einfluss auf Berechnung"}, {"text": "Umsatz", "correct": false, "because": "Grundlage des Gewinns"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Authentizität von Daten entscheidend?', 2, '[{"text": "Identitätsprüfung", "correct": true, "because": "Bestätigt Herkunft"}, {"text": "Farbe der Benutzeroberfläche", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Authentizität richtig? a) Sie stellt sicher, dass Daten echt sind. b) Sie schützt vor Datenverlust.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Echtheit, nicht Verlustschutz"}, {"text": "Beides stimmt", "correct": false, "because": "Verlust ist Verfügbarkeit"}, {"text": "Nur b) stimmt", "correct": false, "because": "Echtheit ist Kern"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Verbindlichkeit immer durch digitale Signaturen gesichert?', 1, '[{"text": "Nein", "correct": true, "because": "Andere Methoden möglich"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich Signaturen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schutzziele sind für die Verbindlichkeit wichtig?', 5, '[{"text": "Authentizität", "correct": true, "because": "Bestätigt Identität"}, {"text": "Integrität", "correct": true, "because": "Sichert Unveränderbarkeit"}, {"text": "Schriftgröße der Logs", "correct": false, "because": "Kein Einfluss"}, {"text": "Vertraulichkeit", "correct": true, "because": "Schützt Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Sicherstellung der Verbindlichkeit ignorieren?', 2, '[{"text": "Digitale Signaturen", "correct": false, "because": "Wichtig für Nachweis"}, {"text": "Farbe der Benutzeroberfläche", "correct": true, "because": "Kein Einfluss"}, {"text": "Protokollierung", "correct": false, "because": "Sichert Nachverfolgbarkeit"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Verfügbarkeit von IT-Systemen entscheidend?', 2, '[{"text": "Redundanz", "correct": true, "because": "Sichert Zugriff bei Ausfall"}, {"text": "Design der Server", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Schutzziele richtig? a) Verfügbarkeit schützt vor Datenverlust. b) Verbindlichkeit stellt sicher, dass Aktionen nachweisbar sind.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Verfügbarkeit schützt nicht direkt"}, {"text": "Nur b) stimmt", "correct": true, "because": "Verbindlichkeit ist Nachweis"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist ungenau"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist korrekt"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
