('00000000-0000-0000-0000-000000000000', 'Welche Schutzziele sind für sichere Kommunikation wichtig?', 5, '[{"text": "Verfügbarkeit", "correct": true, "because": "Sichert Zugriff"}, {"text": "Authentizität", "correct": true, "because": "Bestätigt Identität"}, {"text": "Farbe der Daten", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Verbindlichkeit", "correct": true, "because": "Beweist Nachvollziehbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Sicherstellung der Authentizität ignorieren?', 2, '[{"text": "Passwörter", "correct": false, "because": "Wichtig für Verifizierung"}, {"text": "Farbe der Benutzeroberfläche", "correct": true, "because": "Kein Einfluss"}, {"text": "Zwei-Faktor-Authentifizierung", "correct": false, "because": "Erhöht Sicherheit"}]');
