('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verschlüsselung schützt Daten während der Übertragung. b) Zugriffskontrollen sind nur für physische Systeme relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zugriffskontrollen auch digital"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage b) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "Verschlüsselung schützt"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System solltest du priorisieren, um ungewöhnliche Aktivitäten im Netzwerk zu erkennen?', 4, '[{"text": "Intrusion Detection System (IDS)", "correct": true, "because": "Erkennt Anomalien"}, {"text": "Backup-Systeme", "correct": false, "because": "Nur Wiederherstellung"}, {"text": "Farbe der Benutzeroberfläche", "correct": false, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Virenschutz ohne Firewall effektiv sein?', 2, '[{"text": "Ja", "correct": true, "because": "Schützt gegen Malware unabhängig"}, {"text": "Nein", "correct": false, "because": "Firewall nicht zwingend nötig"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
