INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Virenschutz immer ausreichend, um ein System vor allen Bedrohungen zu schützen?', 2, '[{"text": "Nein", "correct": true, "because": "Nur spezifisch gegen Malware"}, {"text": "Ja", "correct": false, "because": "Andere Bedrohungen bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme schützt ein Netzwerk vor unerlaubtem Zugriff?', 3, '[{"text": "Firewall", "correct": true, "because": "Regelt Datenverkehr"}, {"text": "Farbe der Hardware", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Schriftart der Konfiguration", "correct": false, "because": "Nur Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verschlüsselung schützt Daten während der Übertragung. b) Ein IDS verhindert Angriffe aktiv.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IDS erkennt, stoppt nicht"}, {"text": "Beides stimmt", "correct": false, "because": "IDS ist passiv"}, {"text": "Nur b) stimmt", "correct": false, "because": "Verschlüsselung schützt"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme solltest du priorisieren, um sensible Daten vor unbefugtem Zugriff zu schützen?', 4, '[{"text": "Verschlüsselung", "correct": true, "because": "Verhindert Einsicht"}, {"text": "Farbe der Benutzeroberfläche", "correct": false, "because": "Kein Schutz"}, {"text": "Design der Software", "correct": false, "because": "Ästhetisch, nicht sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Zugriffskontrollsystem ohne Authentifizierung funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Authentifizierung ist Grundlage"}, {"text": "Ja", "correct": false, "because": "Ohne Identität unsicher"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei Backup-Systemen entscheidend?', 2, '[{"text": "Regelmäßige Durchführung", "correct": true, "because": "Sichert Datenverfügbarkeit"}, {"text": "Farbe der Backup-Medien", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Netzwerksegmentierung ohne Firewall effektiv?', 1, '[{"text": "Ja", "correct": true, "because": "Segmentierung allein begrenzt Schaden"}, {"text": "Nein", "correct": false, "because": "Firewall nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sind für die Systemsicherheit wichtig?', 5, '[{"text": "Updates/Patch-Management", "correct": true, "because": "Schließt Schwachstellen"}, {"text": "Authentifizierungssysteme", "correct": true, "because": "Verifiziert Zugriff"}, {"text": "Farbe der Protokollanzeige", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Sicherheitsprotokollierung", "correct": true, "because": "Dokumentiert Vorfälle"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über technische Maßnahmen richtig? a) Backup-Systeme schützen vor Datenverlust. b) Updates sind nur für neue Funktionen wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Updates auch für Sicherheit"}, {"text": "Beides stimmt", "correct": false, "because": "Updates nicht nur Funktionen"}, {"text": "Nur b) stimmt", "correct": false, "because": "Backups schützen"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Implementierung von Sicherheitsprotokollierung ignorieren?', 2, '[{"text": "Protokollhäufigkeit", "correct": false, "because": "Wichtig für Nachverfolgung"}, {"text": "Farbe der Protokolldateien", "correct": true, "because": "Kein Einfluss"}, {"text": "Speicherort der Logs", "correct": false, "because": "Entscheidend für Sicherheit"}]');
